strict=[r for r in rows if r['\\''ModelID'\\'']"'!='"'\\''pDNA'\\'' and r['\\''ScreenType'\\'']"'!='"'\\''pDNA'\\'' and all(r[k].strip().lower()==v for k,v in [('\\''PassesQC'\\'','\\''true'\\''),('\\''DrugTreated'\\'','\\''false'\\''),('\\''IsEngineered'\\'','\\''false'\\''),('\\''ExcludeFromCRISPRCombined'\\'','\\''false'\\'')]) and r['\\''Library'\\''].strip()]
strict_nodes={r['\\''ModelConditionID'\\''] for r in strict}
